# Dual-run compare (generated by bh-migrate)

COMPARE_PAIRS = [{'left_ref': 'databricks-migrate-activity.schema1.customer_events_dual_clone_1', 'right_ref': 'databricks-migrate-activity.schema1.customer_events_dual_clone_2', 'label': 'customer_events'}]
COMPARE_CONFIG = {'enabled': True, 'report': {'root_uri': 'gs://migration-dualrun/reports', 'summary_json': True, 'summary_markdown': True, 'summary_html': False, 'detail_format': 'delta', 'write_audit_tables': True, 'audit_catalog': 'migration_audit', 'audit_schema': 'dualrun'}, 'row_details': {'enabled': True, 'max_issue_rows_per_table': None, 'max_sample_rows_in_summary': 100, 'include_full_row_json': True, 'include_column_diff_json': True, 'include_mismatch_columns': True, 'max_json_length': 100000}, 'comparison_rules': {'fail_on_duplicate_keys': True, 'ignored_columns': ['_commit_timestamp', '_commit_version', '_change_type', '_change_ordinal', 'run_id', 'load_ts', 'updated_at'], 'sensitive_columns': [], 'numeric_tolerances': {}, 'timestamp_tolerance_seconds': 0}, 'checks': {'enable_basic_stats': True, 'enable_null_stats': True, 'enable_distinct_stats': True, 'enable_numeric_stats': True, 'enable_datetime_stats': True, 'enable_distribution_stats': True, 'enable_row_comparison': True, 'enable_delta_operation_metrics': True, 'enable_delta_version_stats': True, 'enable_distribution_by_status': False}, 'filters': {'business_date': None, 'where_clause': None}, 'runtime': {'fail_process_on': ['FAIL', 'BLOCKED']}, 'numeric_columns': None}
DEFAULT_REPORT_ROOT = 'gs://migration-dualrun/reports'

import argparse
import base64
import gzip

from pyspark.sql import SparkSession


def _load_compare_engine():
    payload = gzip.decompress(base64.b64decode("".join(_COMPARE_ENGINE_B64)))
    namespace = {"__name__": "compare_engine"}
    exec(compile(payload.decode("utf-8"), "compare_engine.py", "exec"), namespace)
    return namespace


def main(argv=None):
    parser = argparse.ArgumentParser(description="Execute dual-run output comparison")
    parser.add_argument("--dual-run-id", required=True)
    parser.add_argument("--candidate-id", required=True)
    parser.add_argument("--project-name", required=True)
    parser.add_argument("--report-root", default=DEFAULT_REPORT_ROOT)
    args = parser.parse_args(argv)

    engine = _load_compare_engine()
    ComparePair = engine["ComparePair"]
    CompareRunContext = engine["CompareRunContext"]
    compare_config_from_dict = engine["compare_config_from_dict"]
    DualRunComparatorExecutor = engine["DualRunComparatorExecutor"]
    LocalReportSink = engine["LocalReportSink"]

    pairs = [
        ComparePair(
            left_ref=str(item["left_ref"]),
            right_ref=str(item["right_ref"]),
            label=item.get('label'),
            key_columns=item.get('key_columns'),
            partition_columns=item.get('partition_columns'),
            comparable_columns=item.get('comparable_columns'),
            numeric_columns=item.get('numeric_columns'),
            date_columns=item.get('date_columns'),
            timestamp_columns=item.get('timestamp_columns'),
            status_column=item.get('status_column'),
            ignored_columns=item.get('ignored_columns'),
        )
        for item in COMPARE_PAIRS
    ]
    config = compare_config_from_dict(COMPARE_CONFIG)

    spark = SparkSession.builder.appName(f"dual-run-compare-{args.dual_run_id}").getOrCreate()
    context = CompareRunContext(
        dual_run_id=args.dual_run_id,
        candidate_id=args.candidate_id,
        project_name=args.project_name,
        report_root=args.report_root,
    )
    sink = LocalReportSink()
    executor = DualRunComparatorExecutor(spark=spark, config=config, report_sink=sink)
    report = executor.execute(context, pairs)
    if executor.should_fail_process(report):
        return 1
    return 0


